// Every loader-map entry below carries the generator-owned presence
// classification: resolution "required" (cinatra.systemExtensions member —
// unguarded import, absence fails loudly) | "guardedOptional" (loader
// routes through the standardized degraded-result guard,
// src/lib/extension-load-guard.ts — post-build absence degrades per entry).
// Downstream gates key EXCLUSIVELY on this field (missing/unknown ⇒
// required, fail-closed).
export type GeneratedExtensionLoaderEntry = {
  resolution: ExtensionResolution;
  load: () => Promise<unknown>;
};

